const blankText = (): LocalizedText => ({ he: "", ar: "", en: "" });
const promptText = (): LocalizedText => ({ he: "פריט חדש", ar: "عنصر جديد", en: "New item" });
const safeId = (value: string) => value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60);
